projects:
import manifest from "./image-manifest.json";
export const categories = ["Domy", "Obiekty usługowe", "Wnętrza"] as const;
export type ProjectImage = {
  src: string;
  alt: string;
  width: number;
  height: number;
  objectPosition?: string;
};
export type Project = {
  slug: string;
  title: string;
  category: (typeof categories)[number];
  location?: string;
  year?: number;
  description: string;
  cover: ProjectImage;
  images: ProjectImage[];
  credits: { authorship: "pending-confirmation"; note: string };
  publicationStatus: "draft" | "pending-confirmation";
  featuredOrder?: number;
};
const images = (slug: string): ProjectImage[] =>
  manifest
    .filter((image) => image.src.startsWith(`/images/projects/${slug}/`))
    .map(({ src, alt, width, height }) => ({ src, alt, width, height }));
const entries: Omit<
  Project,
  "images" | "cover" | "credits" | "publicationStatus"
>[] = [
  {
    slug: "dom-w-lodzi",
    title: "Dom w Łodzi",
    category: "Domy",
    description:
      "Jasna, piętrowa bryła otwarta na ogród. Zadaszony taras łączy strefę dzienną z zielenią.",
    featuredOrder: 1,
  },
  {
    slug: "dom-z-ciemna-elewacja",
    title: "Dom z ciemną elewacją",
    category: "Domy",
    description:
      "Ciemna elewacja podkreśla horyzontalny układ domu. Duże przeszklenia i taras otwierają wnętrze na ogród.",
    featuredOrder: 2,
  },
  {
    slug: "spa-ze-stajnia",
    title: "SPA ze stajnią",
    category: "Obiekty usługowe",
    location: "Łódź",
    year: 2025,
    description:
      "Wydłużona bryła, rytm przeszkleń i stonowane materiały. Projekt przestrzeni usługowej łączącej funkcję SPA ze stajnią.",
    featuredOrder: 3,
  },
  {
    slug: "dom-jednorodzinny-lodz",
    title: "Dom jednorodzinny w Łodzi",
    category: "Domy",
    location: "Łódź",
    year: 2024,
    description:
      "Dom jednorodzinny z dwuspadowym dachem i garażem w niższej części bryły. Jasna elewacja kontrastuje z ciemną stolarką i pokryciem dachu.",
    featuredOrder: 4,
  },
  {
    slug: "kuchnia-drewno-kamien",
    title: "Kuchnia w drewnie i kamieniu",
    category: "Wnętrza",
    description:
      "Naturalne drewno i wyrazisty kamień wyznaczają charakter kuchni. Wyspa porządkuje przestrzeń pracy i spotkań.",
    featuredOrder: 5,
  },
  {
    slug: "lazienka-naturalne-odcienie",
    title: "Łazienka w naturalnych odcieniach",
    category: "Wnętrza",
    description:
      "Spokojna paleta, miękkie światło i naturalne faktury. Strefa umywalki i prysznic tworzą spójną przestrzeń.",
    featuredOrder: 6,
  },
  {
    slug: "kuchnia-ciemna-zabudowa",
    title: "Kuchnia w ciemnej zabudowie",
    category: "Wnętrza",
    description:
      "Głęboki odcień zabudowy zestawiony z jasną wyspą. Pionowe kadry pokazują proporcje wnętrza i detale materiałów.",
  },
  {
    slug: "dom-kostka",
    title: "Przebudowa domu typu kostka",
    category: "Domy",
    description:
      "Studium bryły domu typu kostka oraz jego połączenia z tarasem i ogrodem.",
  },
];
export const projects: Project[] = entries.map((entry) => {
  const gallery = images(entry.slug);
  return {
    ...entry,
    images: gallery,
    cover: {
      ...gallery[0],
      objectPosition:
        entry.slug === "lazienka-naturalne-odcienie"
          ? "50% 62%"
          : entry.slug === "kuchnia-drewno-kamien"
            ? "50% 35%"
            : "50% 50%",
    },
    credits: {
      authorship: "pending-confirmation",
      note: "Autorstwo, zakres współpracy i prawa do publikacji do potwierdzenia z Pauliną — patrz docs/DO-POTWIERDZENIA-Z-PAULINA.md.",
    },
    publicationStatus:
      entry.slug === "dom-kostka" ? "pending-confirmation" : "draft",
  };
});
export const portfolioProjects = projects.filter(
  (p) => p.publicationStatus !== "pending-confirmation",
);
export const featuredProjects = portfolioProjects
  .filter((p) => p.featuredOrder)
  .sort((a, b) => a.featuredOrder! - b.featuredOrder!);
export const getProject = (slug: string) =>
  projects.find((project) => project.slug === slug);
